export function renderPlanning(state, ui, {esc, icon, button, dateLabel}) {
  const plan = state.planning || {runs: {}, today: [], receipts: []};
  const mode = ui.planningMode || 'today';
  const entries = [['today', '安排今天', '先看今天的承诺，选出值得推进的行动。', 'calendar'], ['project', '梳理项目', '找出下一步、等待项和需要补充的依据。', 'folder'], ['task', '推进任务', '围绕一条原任务，准备具体的下一步。', 'target']];
  const current = entries.find(entry => entry[0] === mode);
  const active = state.tasks.filter(t => t.state !== 'done');
  const run = plan.runs[mode];
  const task = id => state.tasks.find(t => t.id === id);
  const sourceName = source => ({dida:'滴答', craft:'Craft', feishu:'飞书', obsidian:'Obsidian', hub:'Hub'})[source] || source;
  const stateName = {todo:'待办', doing:'进行中', waiting:'等待条件', done:'已完成'};
  const change = suggestion => suggestion.kind === 'plan' ? '仅加入 Hub 今日计划 · 不改来源' : suggestion.kind === 'note' ? '仅保留 Hub 助手笔记 · 不改来源' : `修改${sourceName(task(suggestion.taskId).source)}的下一步 · 先预览`;
  return `<section class="planning-page" aria-labelledby="planning-title">
    <div class="page-heading"><div><h1 id="planning-title">今天，想推进什么？</h1><p>选一个入口，让建议回到具体任务上。</p></div><span class="prototype-tag">v2 · 示例体验</span></div>
    <nav class="planning-entries" aria-label="AI 任务入口">${entries.map(([key, title, description, glyph]) => `<button type="button" data-action="plan-mode" data-id="${key}" aria-pressed="${mode === key}">${icon(glyph,20)}<strong>${title}</strong><span>${description}</span></button>`).join('')}</nav>
    <div class="planning-grid"><div class="planning-work">
      <form id="planning-form" class="planning-form"><div class="planning-section-title"><h2>${current[1]}</h2><span>先读取，再建议</span></div>
        <p>${mode === 'today' ? '读取全部示例项目的未完成任务；截止承诺全部列出，其余按可用时间建议。' : mode === 'project' ? '聚焦一个项目，结合已有任务和项目资料，检查缺口与等待条件。' : '选择一条任务，读取原任务与相关资料，形成可检查、可采用的下一步。'}</p>
        <div class="planning-inputs">${mode === 'today' ? `<label class="form-field">今天可用的时间<select name="capacity"><option value="60"${ui.planCapacity === '60'?' selected':''}>约 1 小时</option><option value="120"${!ui.planCapacity || ui.planCapacity === '120'?' selected':''}>约 2 小时</option><option value="240"${ui.planCapacity === '240'?' selected':''}>约半天</option></select></label>` : mode === 'project' ? `<label class="form-field">要梳理的项目<select name="project">${[...new Set(active.map(t=>t.project))].map(project => `<option${project === (ui.planProject || 'BEV')?' selected':''}>${esc(project)}</option>`).join('')}</select></label>` : `<label class="form-field">要推进的原任务<select name="taskId">${active.map(t => `<option value="${esc(t.id)}"${t.id === (ui.planTask || 't-harness')?' selected':''}>${esc(t.title)}</option>`).join('')}</select></label>`}
        <label class="form-field">数据情境<select name="coverage"><option value="fresh"${!ui.planCoverage || ui.planCoverage === 'fresh'?' selected':''}>示例数据完整</option><option value="cached"${ui.planCoverage === 'cached'?' selected':''}>离线，使用上次数据</option><option value="partial"${ui.planCoverage === 'partial'?' selected':''}>飞书资料读取失败</option></select></label></div>
        <div class="planning-form-foot"><span>${icon('shield',14)}本次只分析，不改任务</span><button class="btn btn-primary" type="submit"${ui.planningBusy?' disabled':''}>${icon('spark',15)}${ui.planningBusy?'正在读取示例任务…':'读取并生成建议（演示）'}</button></div>
      </form>
      <div class="planning-results" aria-live="polite" aria-busy="${!!ui.planningBusy}">${ui.planningBusy ? '<div class="planning-loading">正在核对所选范围的任务状态和相关资料…</div>' : run ? `
        <div class="planning-coverage ${run.coverage !== 'fresh'?'limited':''}">${icon(run.coverage === 'fresh'?'check':'info',16)}<div><strong>${run.coverage === 'fresh'?'已读取所选范围的示例数据':run.coverage === 'cached'?'以下建议基于旧缓存':'资料不完整：飞书读取失败'}</strong><p>${run.total} 项原任务 · ${run.mode === 'project'?esc(run.project):run.mode === 'task'?esc(task(run.taskId)?.title):'全部示例项目'} · ${run.coverage === 'fresh'?'示例读取': '本次尝试'} ${esc(run.at.slice(11,16) || '刚刚')}<br>${run.coverage === 'cached'?'任务数据截至上次示例快照，未核实远端变化；采纳前需要重新核对。':run.coverage === 'partial'?'任务清单来自本地示例，飞书资料未参与分析；不能据此判断已无遗漏。':'任务来自示例滴答主档；只补读相关资料，没有把全部内容交给模型。'}</p></div></div>
        ${mode === 'today'?'<p class="planning-caveat">未连接日历，也未核实任务耗时。按每项约 30 分钟提供选量参考，时间安排由你调整。</p>':''}
        <div class="planning-section-title"><h2>建议你这样推进</h2><span>${run.suggestions.length} 条建议 · 逐条选择</span></div>
        ${run.suggestions.length ? run.suggestions.map(s => `<article class="planning-suggestion" tabindex="-1" data-suggestion="${esc(s.id)}"><div class="suggestion-heading"><span>${esc(s.title)}</span><small>${esc(stateName[task(s.taskId).state])}</small></div><h3><button type="button" class="btn-link" data-action="plan-task" data-id="${esc(s.taskId)}">${esc(task(s.taskId).title)} ${icon('external',12)}</button></h3><p class="suggestion-reason">${esc(s.reason)}</p><p>${esc(s.text)}</p><details><summary>查看依据与原任务</summary><p>${sourceName(task(s.taskId).source)} / ${esc(task(s.taskId).list)} · 原任务 ${esc(s.taskId)}<br>原截止：${dateLabel(task(s.taskId).due)} · 原状态：${stateName[task(s.taskId).state]}</p>${s.evidence?.length?s.evidence.map(id=>{const m=state.materials.find(m=>m.id===id);return `<p>${sourceName(m.source)} · ${esc(m.title)}<br>${esc(m.body)}</p>`;}).join(''):'<p>本条只依据原任务，没有取得额外资料。</p>'}</details><div class="adoption-effect">${icon(s.kind === 'nextStep'?'edit':'link',13)}${change(s)}</div><div class="suggestion-actions">${s.status === 'pending' ? `${button('plan-adopt',s.kind === 'plan'?'加入今日计划':s.kind === 'note'?'保留建议':'预览来源修改','btn btn-primary btn-small',s.id)}${button('plan-dismiss','暂不采用','btn btn-small',s.id)}` : s.status === 'adopted' ? `<span class="adoption-success">${icon('check',14)}${s.kind === 'plan'?'已加入今日计划，原任务未改动':s.kind === 'note'?'建议已保留，任务尚未完成':'演示来源已确认更新'}</span>` : s.status === 'dismissed' ? '<span>已暂不采用 · 原任务保持原样</span>' : s.status === 'failed' ? `<span class="planning-error">模拟保存失败，来源未改动</span>${button('plan-retry','重试同一操作','btn btn-small',s.id)}` : `<span class="planning-error">结果未知，先核对再决定</span>${button('plan-reconcile','核对模拟来源','btn btn-small',s.id)}`}</div></article>`).join('') : '<div class="empty"><h3>这个范围没有未完成任务</h3><p>换一个项目或任务，重新生成建议。</p></div>'}` : `<div class="planning-empty">${icon('spark',27)}<h2>先看看建议，再决定采用什么</h2><p>生成后会逐条说明依据、建议内容和采纳影响。<br>只查看建议，也可以到此结束。</p></div>`}</div>
    </div><aside class="planning-aside"><div class="planning-section-title"><h2>我的今日计划</h2><span>Hub 本机</span></div><p>只引用原任务，不复制，也不改原截止。</p>${plan.today.filter(id=>task(id).state !== 'done').map(id => `<div class="planned-reference"><button data-action="plan-task" data-id="${esc(id)}">${esc(task(id).title)}</button><small>${sourceName(task(id).source)} · ${esc(task(id).project)}</small>${button('plan-remove','移出计划','btn btn-link',id)}</div>`).join('') || '<div class="planning-aside-empty">尚未选择任务。<br>从左侧建议中加入。</div>'}
      <div class="planning-section-title receipt-title"><h2>采纳记录</h2></div>${plan.receipts.slice(0,5).map(r=>`<div class="planning-receipt"><strong>${esc(task(r.taskId).title)}</strong><p>${esc(r.message)}</p></div>`).join('') || '<p>采用建议后，这里会说明实际做了什么。</p>'}
      <div class="planning-boundary"><strong>这是一次流程体验</strong><p>所有任务、AI 建议和来源保存均为模拟；不访问真实账户。旧任务视图和完整案例仍在左侧“任务”入口。</p></div>
    </aside></div></section>`;
}
